  $('cT').addEventListener('mousemove', e => { const td = e.target.closest('[data-p]'); if (!td) { untip(); return; } const [p, q] = td.dataset.p.split('|'); tip(e, `${p} / ${q} : <b>${td.textContent || '—'}</b>`); }); $('cT').addEventListener('mouseleave', untip);
