  const hy = half.slice().reverse().filter(h => h.win != null && h.sum != null).slice(-20); barChart($('sH'), { labels: hy.map(h => String(h.y).slice(2)), values: hy.map(h => (h.win - h.sum) * 100), fmt: v => num(v, 1) + '%', extra: i => `hiver ${num(hy[i].win * 100, 1)}% · été ${num(hy[i].sum * 100, 1)}%` });
